const sourceType = $json['Source Type'];
const content = ($json['Content'] || '').trim();
const pageUrl = ($json['Page URL'] || '').trim();
const sheetUrl = ($json['Google Sheet URL'] || '').trim();
const hasFile = Boolean($binary && $binary['File'] && $binary['File'].fileName);

let valid = false;
let reason = '';

if (sourceType === 'Paste text') {
  valid = content.length > 0;
  reason = 'Source Type is "Paste text" but the Content field is empty.';
} else if (sourceType === 'Website page') {
  valid = /^https?:\/\//.test(pageUrl);
  reason = 'Source Type is "Website page" but Page URL is empty or not a valid http(s) URL.';
} else if (sourceType === 'File (PDF or Word)') {
  valid = hasFile;
  reason = 'Source Type is "File (PDF or Word)" but no file was attached.';
} else if (sourceType === 'Google Sheet') {
  valid = /^https?:\/\/docs\.google\.com\/spreadsheets\//.test(sheetUrl);
  reason = 'Source Type is "Google Sheet" but Google Sheet URL is empty or not a docs.google.com/spreadsheets link.';
} else {
  reason = 'Unrecognized Source Type: ' + sourceType;
}

return [{ json: { ...$json, sourceValid: valid, sourceValidationReason: reason } }];

const title = $('KB Upload Form').item.json['Document title'];
const content = $('Merge Content Sources').item.json.resolvedContent;
const customerId = $('Load Customer').item.json.id;
const businessName = $('Load Customer').item.json.business_name;

const MAX_CHARS = 1200;
const OVERLAP = 150;
const MIN_CHUNK = 400; // don't hunt for a boundary so far back that a chunk becomes tiny

// Prefer breaking at a paragraph gap, then a sentence end, then a line break,
// only falling back to a hard character cut if none exist near the target
// size. Added 2026-08-13: the previous version sliced at a fixed character
// count with no regard for word/sentence boundaries, so a price line or
// sentence could be split in half across two chunks, degrading retrieval
// (the model sees half a fact per chunk instead of a whole one).
function findBreakPoint(text, idealEnd) {
  const windowStart = Math.max(MIN_CHUNK, idealEnd - 300);
  const window = text.slice(windowStart, idealEnd);

  const paraBreak = window.lastIndexOf('\n\n');
  if (paraBreak !== -1) return windowStart + paraBreak + 2;

  const sentenceMatch = [...window.matchAll(/[.!?]\s/g)].pop();
  if (sentenceMatch) return windowStart + sentenceMatch.index + sentenceMatch[0].length;

  const lineBreak = window.lastIndexOf('\n');
  if (lineBreak !== -1) return windowStart + lineBreak + 1;

  return idealEnd; // no natural boundary found, hard cut as last resort
}

function chunk(text) {
  const clean = text.replace(/\r\n/g, '\n').trim();
  if (clean.length <= MAX_CHARS) return [clean];

  const chunks = [];
  let start = 0;
  while (start < clean.length) {
    const idealEnd = Math.min(start + MAX_CHARS, clean.length);
    const end = idealEnd === clean.length ? idealEnd : findBreakPoint(clean, idealEnd);
    chunks.push(clean.slice(start, end).trim());
    if (end >= clean.length) break;
    start = Math.max(end - OVERLAP, start + 1); // always advance, even if OVERLAP would otherwise stall on a short boundary
  }
  return chunks;
}

const chunks = chunk(content);

return chunks.map((text, i) => ({
  json: {
    customerId,
    businessName,
    title,
    chunkIndex: i,
    chunkCount: chunks.length,
    text: `${title}\n\n${text}`,
  },
}));

const rows = $input.all().map(item => item.json);
if (rows.length === 0) {
  return [{ json: { resolvedContent: '' } }];
}

const columns = Object.keys(rows[0]).filter(k => k !== 'row_number');

// Flatten each row into a plain-text line, e.g. "Product: Widget | Price: 5000 | Stock: 12"
// rather than dumping raw JSON, since this text is what the AI reads at answer time,
// not parsed as structured data downstream.
const lines = rows.map(row => columns.map(col => `${col}: ${row[col]}`).join(' | '));

return [{ json: { resolvedContent: lines.join('\n') } }];

// Added 2026-08-13. Deliberately not a Merge node here: n8n's Merge node
// modes (chooseBranch, combine/position, etc.) are documented and confirmed
// as fundamentally 2-input concepts, or as waiting on ALL connected inputs
// before proceeding. With 4 branches where only one ever actually produces
// data (the other 3 are dead-end IF branches with zero items), that risks
// either a hang or unpredictable field-merging behavior. Using
// $('NodeName').isExecuted (confirmed safe, does not throw) to check each
// candidate node directly instead, no ambiguity, no wait semantics.
const candidates = [
  'Resolve Content (Paste)',
  'Resolve Content (Website)',
  'Resolve Content (File)',
  'Resolve Content (Sheet)',
];

for (const name of candidates) {
  if ($(name).isExecuted) {
    return [{ json: { resolvedContent: $(name).item.json.resolvedContent } }];
  }
}

throw new Error('Merge Content Sources: none of the 4 Resolve Content branches executed, this should be unreachable given Validate Source Fields already ran.');
